import{_ as o,o as d,c as t,a5 as c}from"./chunks/framework.BjM_ivYE.js";const m=JSON.parse('{"title":"매뉴얼 작성 규약","description":"","frontmatter":{},"headers":[],"relativePath":"STYLE.md","filePath":"STYLE.md","lastUpdated":1789720047000}'),l={name:"STYLE.md"};function a(i,e,r,s,n,g){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="매뉴얼-작성-규약" tabindex="-1">매뉴얼 작성 규약 <a class="header-anchor" href="#매뉴얼-작성-규약" aria-label="Permalink to &quot;매뉴얼 작성 규약&quot;">​</a></h1><p><code>docs/manual/</code> 을 고칠 때 지킬 형식과 어투. <strong>기존 페이지가 곧 견본이다</strong> — 고치기 전에 같은 페이지를 끝까지 읽고, 그 페이지가 이미 쓰는 형태를 따른다. 새 형태를 발명하지 않는다.</p><p><strong>적용 대상</strong> — 아래 &quot;형식&quot;의 컨테이너·이미지 문법은 <strong>앱 절(<code>docs/manual/gui/</code>)</strong> 의 형태다. 나머지 절 (하드웨어·운용·유지보수·안전·인터페이스·트러블슈팅 등)은 HTML 을 쓴다 — 경고는 <code>&lt;div class=&quot;sb sb-note&quot;&gt;</code>, 그림은 <code>&lt;figure&gt;&lt;img …&gt;</code>. 그 절을 고칠 때는 그 형태를 그대로 쓰고 마크다운 컨테이너로 바꾸지 않는다. 한/영 짝·앵커·라벨·어투·레벨 규칙은 매뉴얼 전체 공통이다. 기계로 검사되는 항목은 <code>.github/scripts/docs_form.py</code> 가 잡는다(형식만 — 어투는 AI 리뷰가 본다).</p><h2 id="형식" tabindex="-1">형식 <a class="header-anchor" href="#형식" aria-label="Permalink to &quot;형식&quot;">​</a></h2><ul><li>파일 머리는 <code>---</code> / <code>layout: doc</code> / <code>outline: deep</code> / <code>---</code>. 그다음 <code>#</code> 제목 하나.</li><li>절은 <code>##</code>, 하위는 <code>###</code>. 다른 페이지가 가리키는 절에는 앵커를 단다 — <code>## Settings {#settings}</code>. 앵커를 지우거나 이름을 바꾸면 그 앵커를 가리키던 링크가 죽는다. 먼저 <code>grep</code> 으로 참조를 찾아라.</li><li>경고는 컨테이너로. <code>::: warning</code>(주의) <code>::: danger</code>(사람이 다칠 수 있음) <code>::: tip</code>(옵션 장비 안내). 본문에 굵게 써서 대신하지 않는다.</li><li>UI 라벨은 백틱. <code>`E-STOP`</code> <code>`Save &amp; Connect`</code>. 앱 문자열과 글자 그대로 같아야 한다 — <code>gui/src/lib/i18n.en.ts</code> 가 <strong>한국어 원문을 키, 영어를 값</strong>으로 담으므로 한국어 페이지는 키를, 영어 페이지는 값을 쓴다. 화면 이름·카드 이름은 굵게(<strong>CONTROL</strong>).</li><li>이미지는 <code>docs/public/images/app/</code> 의 <code>&lt;id&gt;.&lt;axis&gt;.&lt;lang&gt;.png</code> 또는 번호 주석을 구운 <code>&lt;id&gt;.annotated.&lt;lang&gt;.png</code>. 영어 페이지는 <code>.en</code>, 한국어는 <code>.ko</code>. 캡처·주석은 <code>docs/scripts/controller-atlas/</code>(사용법 README, 규약·함정 <code>.claude/skills/controller-atlas/SKILL.md</code>)로 만든다 — <strong>매뉴얼에 실리는 그림은 <code>manual-shots.mjs</code> + <code>manual-capture.mjs</code></strong>(앱 데모 모드로 찍는다), 화면 도감은 <code>shots.mjs</code>. 새 화면이 필요하면 해당 파일에 컷을 추가한다. 손으로 찍은 캡처를 섞지 않는다.</li><li>개발자 모드 내용은 각 페이지에 풀어 쓰지 않고 한 줄로 넘긴다. 문장은 이 형태를 그대로 쓴다. <ul><li>영어: <code>&gt; **What developer mode adds here** is collected on [Developer mode](/manual/gui/developer-mode#&lt;앵커&gt;).</code></li><li>한국어: <code>&gt; **개발자 모드에서 더 나오는 것**은 [개발자 모드](/ko/manual/gui/developer-mode#&lt;앵커&gt;)에 모아 두었습니다.</code></li></ul></li><li><strong>영어 원문과 <code>docs/ko/</code> 짝은 같은 구조다.</strong> 제목 개수·순서·앵커·이미지 수·컨테이너 종류가 같아야 한다. 한쪽만 고치지 않는다.</li></ul><h2 id="어투" tabindex="-1">어투 <a class="header-anchor" href="#어투" aria-label="Permalink to &quot;어투&quot;">​</a></h2><ul><li>영어: 2인칭 현재형, 짧고 평이하게. 기능이 무엇을 하는지 먼저, 조건은 뒤에. 견본 — <em>The control home is the screen the app opens on and the one you drive from.</em></li><li>한국어: 존댓말 <code>~합니다</code>. 번역투를 피하고 같은 뜻을 한국어 문장으로 다시 쓴다. 견본 — <em>제어 홈은 앱을 켜면 처음 나오는 화면이자 로봇을 조종하는 화면입니다.</em></li><li>독자는 로봇 운용자와 고객 개발자다. 내부 구현(스토어, REST 경로, CI, 파일 구조)은 쓰지 않는다.</li><li>확인하지 않은 동작을 쓰지 않는다. 코드로 확인되지 않으면 문장을 빼고 담당자에게 남긴다.</li></ul><h2 id="범위" tabindex="-1">범위 <a class="header-anchor" href="#범위" aria-label="Permalink to &quot;범위&quot;">​</a></h2><ul><li><strong>접근 레벨 3(내부) 기능은 문서에 넣지 않는다.</strong> 레벨 2 는 <code>developer-mode.md</code> 로.</li><li>새 페이지·새 절을 만드는 것은 구성 변경이다. 임의로 만들지 말고 문서 담당자와 정한다. 기존 페이지 안에서 해결되면 그렇게 한다.</li><li>화면이 바뀌어 스크린샷이 낡았으면 <code>controller-atlas</code> 로 다시 찍는다. 다시 찍을 수 없으면 그 사실을 PR 에 남긴다 — 낡은 그림을 그대로 두지 않는다.</li></ul>',9)])])}const p=o(l,[["render",a]]);export{m as __pageData,p as default};
